 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    exterior = [[False] * w for _ in range(h)]
    queue = deque()

    # Zero cells connected to the grid boundary are exterior.
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not exterior[nr][nc]):
                exterior[nr][nc] = True
                queue.append((nr, nc))

    # Enclosed background becomes 3; the one-cell 8-neighbor exterior halo
    # around the 1-colored outlines becomes 2.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if not exterior[r][c]:
                out[r][c] = 3
            else:
                near_outline = any(
                    0 <= r + dr < h and 0 <= c + dc < w
                    and grid[r + dr][c + dc] == 1
                    for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                    if dr or dc
                )
                if near_outline:
                    out[r][c] = 2
    return out


if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin))))
